function localImageUrl(id) {
  return LOCAL_IMAGES.has(id) ? `/images/${id}.jpg` : null;
}

const PORTRAIT_URL =
  "https://static.wixstatic.com/media/f3aabf_d4a4d16832cc404a93c3e848ed570c97~mv2.png";

// 2016 Bar-Ilan University / Leiber Center for Jewish Art solo exhibition
// catalog ("Ani Me'atzmi" / "Me, By Myself"), including Dr. Mor Presiado's
// scholarly essay on Jewish symbolism in Barmatz's work.
const EXHIBITION_CATALOG_URL =
  "https://jart.biu.ac.il/sites/jart/files/shared/Art-and-Research/leiber-bremetz-vol2.pdf";

// The "Arie Barmatz Collection" archive page at the National Library of
// Israel (personal papers, letters, and autographs from his estate).
const NLI_ARCHIVE_URL =
  "https://www.nli.org.il/he/archives/NNL_ARCHIVE_AL997011942466905171/NLI";

// 1974 "Ziyur U'Pisul" article by Leah Majro-Mintz on Jerusalem's "percent
// for art" committee, reproduced by Marcel Art Projects, naming Barmatz as
// a committee member overseeing public art in the city's schools.
const MARCEL_ARTICLE_URL =
  "https://www.marcel-art-projects.org/pov/texts/%D7%A4%D7%AA%D7%97-%D7%9C%22%D7%A2%D7%99%D7%A7%D7%A8%D7%95%D7%9F-%D7%94%D7%90%D7%97%D7%95%D7%96%22-%D7%91%D7%99%D7%A8%D7%95%D7%A9%D7%9C%D7%99%D7%9D";

// Video of Arie sharing memories with alumni of the Bnei Akiva "Ge'ulim"
// youth troop he mentored, recorded at his home (2013/2014).
const BNEI_AKIVA_VIDEO_URL = "https://www.youtube.com/watch?v=q6-awg4Z2Sg";

// Every N-th row (by order in the sheet) is shown on the "Selected Works"
// page as a placeholder curation — replace with a real list of IMG numbers
// once you know which pieces you want featured, e.g.
// const SELECTED_IDS = new Set(["770","908","2489", ...]);
const SELECTED_EVERY_N = 40;

// Full archive data, embedded directly (no live network fetch — this makes
// the site load instantly and reliably everywhere, including sandboxed
// previews). Each row's image comes from a verified Drive file ID pulled
